proc pPlainSymbol*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkAccent}):
    expect p, tkAccent
    let m13 = mark(p)
    let m14 = mark(p)
    if (p.tok.kind in {tkAddr..tkYield}):
      emitLeaf p            # KEYW
    elif (p.tok.kind in {tkSymbol}):
      emitLeaf p            # IDENT
    elif (p.tok.kind in Tk11):
      pQuotedLiteral p
    elif (p.tok.kind in Tk12):
      pQuotedPunct p
    else:
      error p, "expected alternative"
    discardUnused m14
    discardUnused m13
    while (p.tok.kind in Tk13):
      let m13 = mark(p)
      let m15 = mark(p)
      if (p.tok.kind in {tkAddr..tkYield}):
        emitLeaf p            # KEYW
      elif (p.tok.kind in {tkSymbol}):
        emitLeaf p            # IDENT
      elif (p.tok.kind in Tk11):
        pQuotedLiteral p
      elif (p.tok.kind in Tk12):
        pQuotedPunct p
      else:
        error p, "expected alternative"
      discardUnused m15
      discardUnused m13
    expect p, tkAccent
    wrap p, m0, "quoted"
  elif (p.tok.kind in {tkSymbol}):
    emitLeaf p            # IDENT
  else:
    error p, "expected plainSymbol"
  discardUnused m0

