proc pQuotedPunct*(p: var Parser) =
  let m0 = mark(p)
  let m16 = mark(p)
  let m17 = mark(p)
  if (p.tok.kind in {tkOpr}):
    emitLeaf p            # OPR
  elif (p.tok.kind in {tkDot}):
