            let m41 = mark(p)
            pushIndAny p
            pSemiStmtList p
            popInd p
            discardUnused m41
          pOptPar p
          expect p, tkParRi
          let m = m0
          stmtListExprLayout p, m
        elif (p.tok.kind in {tkColon}):
          let m42 = mark(p)
          expect p, tkColon
