proc pPrimarySuffix*(p: var Parser; anchor: Mark; mode: PrimaryMode) =
  let m0 = mark(p)
  if ((p.tok.kind in {tkBracketLe, tkCurlyLe, tkParLe})) and noSpaceBefore(p):
