      wrap p, anchor, "at"
    elif (p.tok.kind in {tkCurlyLe}):
      expect p, tkCurlyLe
      if (p.tok.kind in {tkComment} and indClass(p) in {icNoInd, icGt}):
        let m57 = mark(p)
