        discardUnused m58
      pOptPar p
      expect p, tkCurlyRi
      wrap p, anchor, "curlyat"
    else:
      error p, "expected primarySuffix"
  elif (p.tok.kind in {tkDot}):
    expect p, tkDot
    pOptInd p
    pSymbolOrKeyword p
    if ((p.tok.kind in {tkBracketLeColon})) and noSpaceBefore(p):
      let m59 = mark(p)
      expect p, tkBracketLeColon
      pExprList p
      expect p, tkBracketRi
