  else:
    pTypeDefExpr p
    if (p.tok.kind in {tkNot} and indClass(p) in {icNoInd}):
      let m255 = mark(p)
      checkInd p, {icNoInd}
      insertTokAt p, m0, tkNot
      pPrimary(p, pmTypeDesc)
      wrap p, m0, "infix"
      discardUnused m255
  discardUnused m0

